    for (auto& row : g) cin >> row;      // każdy wiersz planszy
    int sx = -1, sy = -1;
    for (int i = 0; i < n; i++)
        for (int j = 0; j < m; j++)
            if (g[i][j] == 'S') { sx = i; sy = j; }
    cout << "start: " << sx << ' ' << sy << '\n';
    // sąsiedzi pola (i, j):
    int dx[] = {-1, 1, 0, 0}, dy[] = {0, 0, -1, 1};
    for (int d = 0; d < 4; d++) {
        int x = sx + dx[d], y = sy + dy[d];
        if (x < 0 || x >= n || y < 0 || y >= m) continue; // poza planszą
        if (g[x][y] == '#') continue;
        cout << "sasiad " << x << ' ' << y << '\n';
    }
}

