#include <bits/stdc++.h>
using namespace std;

static char buf[1 << 16];
static size_t bufLen = 0, bufPos = 0;

inline int readChar() {
    if (bufPos == bufLen) {
        bufLen = fread(buf, 1, sizeof(buf), stdin);
        bufPos = 0;
        if (bufLen == 0) return EOF;
    }
    return buf[bufPos++];
}

// Zwraca false, gdy skończyło się wejście.
inline bool readInt(long long& out) {
    int c = readChar();
    while (c != EOF && c != '-' && (c < '0' || c > '9')) c = readChar();
    if (c == EOF) return false;
    bool neg = false;
    if (c == '-') { neg = true; c = readChar(); }
    long long x = 0;
    while (c >= '0' && c <= '9') { x = x * 10 + (c - '0'); c = readChar(); }
    out = neg ? -x : x;
    return true;
}

int main() {
    long long n, x, s = 0;
    readInt(n);
    for (long long i = 0; i < n; i++) { readInt(x); s += x; }
    printf("%lld\n", s);
}

#include <bits/stdc++.h>
using namespace std;

#ifdef _WIN32
#define gc() _getchar_nolock()
#else
#define gc() getchar_unlocked()
#endif

inline int readInt() {
    int c = gc();
    while (c != '-' && (c < '0' || c > '9')) c = gc();
    bool neg = (c == '-');
    if (neg) c = gc();
    int x = 0;
    while (c >= '0' && c <= '9') { x = x * 10 + (c - '0'); c = gc(); }
    return neg ? -x : x;
}

int main() {
    int n = readInt();
    long long s = 0;
    for (int i = 0; i < n; i++) s += readInt();
    printf("%lld\n", s);
}

